export type Difficulty = 'Easy' | 'Medium' | 'Hard'

export interface Submission {
  title: string
  difficulty: Difficulty
  timestamp: number // unix seconds
}

// A realistic sample history — real LeetCode problems and a believable practice
// rhythm, generated by `scripts/generateSampleData.mjs`. It is deliberately
// not any one person's real history: every problem comes from the public
// catalog, and every title the maintainer actually solved is excluded.
//
// Used whenever the cookie is skipped, so the app runs with no cookie and no
// network.
import sampleSubmissions from './sample-2023-2026.json' with { type: 'json' }

export const SAMPLE_SUBMISSIONS: Submission[] = sampleSubmissions as Submission[]

// Whose history the sample file is — shown on the page and in the CLI summary.
// The sample data isn't anyone's real history, so it's attributed to anonymous.
export const SAMPLE_USERNAME = 'anonymous'